1	//! A checkpoint records a local command's inputs before its first write, so an interrupted run can be resumed from
2	//! them or undone ([ADR 13](../../../../docs/adr/0013-interrupted-version-runs-resume-from-a-checkpoint-ref.md)).
3	
4	use std::path::Path;
5	
6	use sha2::{Digest, Sha256};
7	
8	use super::access::GitAccess;
9	use super::VcsError;
10	use crate::CommitSha;
11	
12	/// Where an interrupted `callisto version` run keeps its inputs. A per-worktree ref, so a linked worktree has its own
13	/// checkpoint and never sees or discards another's.
14	pub const VERSION_CHECKPOINT: &str = "refs/worktree/callisto/checkpoint/version";
15	
16	const HEAD_TRAILER: &str = "Callisto-Head";
17	const TAGS_TRAILER: &str = "Callisto-Tags";
18	const VERSION_TRAILER: &str = "Callisto-Version";
19	const DATE_TRAILER: &str = "Callisto-Date";
20	const WORKSPACE_TRAILER: &str = "Callisto-Workspace";
21	
22	/// The inputs a plan reads besides files, recorded in the checkpoint commit's message.
23	#[derive(Clone, Debug, PartialEq, Eq)]
24	pub struct CheckpointFacts {
25	    pub head: String,
26	    pub tags: String,
27	    pub callisto_version: String,
28	    /// The workspace directory inside the repository (empty at the top). Workspaces share a worktree's checkpoint ref,
29	    /// so a run in another workspace must not resume this one's.
30	    pub workspace: String,
31	}
32	
33	/// A recorded checkpoint: a commit whose tree is the working tree, whose first parent is `HEAD` and whose second
34	/// parent records the index.
35	#[derive(Clone, Debug)]
36	pub struct Checkpoint {
37	    pub commit: CommitSha,
38	    pub facts: CheckpointFacts,
39	    /// The date the run planned with (`YYYY-MM-DD`), so a resume on a later day writes the same changelog dates.
40	    pub date: String,
41	}
42	
43	impl GitAccess<'_> {
44	    /// The checkpoint at `name`, or `None` when there is none.
45	    pub fn checkpoint(&self, name: &str) -> Result<Option<Checkpoint>, VcsError> {
46	        let Some(commit) = self.resolve_commit(name)? else {
47	            return Ok(None);
48	        };
49	        let message = self.git_stdout(&["show", "-s", "--no-show-signature", "--format=%B", commit.as_str()])?;
50	        let trailer = |key: &str| {
51	            message
52	                .lines()
53	                .find_map(|line| line.strip_prefix(key)?.strip_prefix(": "))
54	                .unwrap_or_default()
55	                .to_string()
56	        };
57	        Ok(Some(Checkpoint {
58	            facts: CheckpointFacts {
59	                head: trailer(HEAD_TRAILER),
60	                tags: trailer(TAGS_TRAILER),
61	                callisto_version: trailer(VERSION_TRAILER),
62	                workspace: trailer(WORKSPACE_TRAILER),
63	            },
64	            date: trailer(DATE_TRAILER),
65	            commit,
66	        }))
67	    }
68	
69	    /// The facts a checkpoint taken now would record.
70	    pub fn checkpoint_facts(&self, callisto_version: &str) -> Result<CheckpointFacts, VcsError> {
71	        let tags = self.git_stdout(&["for-each-ref", "--format=%(objectname) %(refname)", "refs/tags"])?;
72	        Ok(CheckpointFacts {
73	            head: self.head_sha()?.as_str().to_string(),
74	            tags: crate::release::digest::lower_hex(Sha256::digest(tags.as_bytes())),
75	            callisto_version: callisto_version.to_string(),
76	            workspace: self.root_prefix()?.display().to_string(),
77	        })
78	    }
79	
80	    /// Records `HEAD`, the index, and the working tree under this root (untracked files included, ignored files
81	    /// left out) at `name`, without touching the user's index or working tree.
82	    ///
83	    /// # Errors
84	    ///
85	    /// [`VcsError::CheckpointHeld`] when `name` already exists, so two runs never share one; a failed git command
86	    /// otherwise.
87	    pub fn create_checkpoint(&self, name: &str, facts: &CheckpointFacts, date: &str) -> Result<CommitSha, VcsError> {
88	        let git_dir = self.git_stdout(&["rev-parse", "--absolute-git-dir"])?;
89	        let index = Path::new(&git_dir).join("callisto-checkpoint.index");
90	        let index_str = index.to_string_lossy().into_owned();
91	        let env = [("GIT_INDEX_FILE", index_str.as_str())];
92	        let real_index = self.git_stdout(&["rev-parse", "--git-path", "index"])?;
93	        let real_index = self.root().join(real_index);
94	        let created = (|| {
95	            let index_commit = self.internal_commit(&self.git_stdout(&["write-tree"])?, &[&facts.head], "index")?;
96	            // Seeded from the real index so Git's stat cache spares rehashing every tracked file; without one it is
97	            // built from `HEAD`.
98	            if std::fs::copy(&real_index, &index).is_err() {
99	                self.git_stdout_env(&["read-tree", "HEAD"], &env)?;
100	            }
101	            // A file Git cannot read, or whose line endings `core.safecrlf` objects to, is not something `version`
102	            // reads or writes, so it must not stop the run: it is left out of the record.
103	            let args = ["-c", "core.safecrlf=false", "add", "-A", "--ignore-errors", "--", "."];
104	            let output = self.runner().run_with_env("git", &args, self.root(), &env)?;
105	            if !output.success() && !output.stderr.contains("unable to index") {
106	                return Err(git_failed(&args, self.root(), &output.stderr));
107	            }
108	            let tree = self.git_stdout_env(&["write-tree"], &env)?;
109	            let message = format!(
110	                "callisto checkpoint\n\n{HEAD_TRAILER}: {}\n{TAGS_TRAILER}: {}\n{VERSION_TRAILER}: {}\n{WORKSPACE_TRAILER}: {}\n{DATE_TRAILER}: {date}\n",
111	                facts.head, facts.tags, facts.callisto_version, facts.workspace
112	            );
113	            self.internal_commit(&tree, &[&facts.head, index_commit.as_str()], &message)
114	        })();
115	        std::fs::remove_file(&index).ok();
116	        let commit = created?;
117	        let args = ["update-ref", name, commit.as_str(), ""];
118	        let output = self.runner().run("git", &args, self.root())?;
119	        if !output.success() {
120	            return Err(if output.stderr.contains("already exists") {
121	                VcsError::CheckpointHeld { name: name.to_string() }
122	            } else {
123	                git_failed(&args, self.root(), &output.stderr)
124	            });
125	        }
126	        Ok(commit)
127	    }
128	
129	    /// Removes the checkpoint at `name`; removing one that does not exist is not an error.
130	    pub fn delete_checkpoint(&self, name: &str) -> Result<(), VcsError> {
131	        self.git_stdout(&["update-ref", "-d", name]).map(drop)
132	    }
133	
134	    /// Whether `path` (relative to this root) has an entry in the index.
135	    pub fn is_staged(&self, path: &Path) -> Result<bool, VcsError> {
136	        let path = path.to_string_lossy();
137	        self.git_stdout(&["--literal-pathspecs", "ls-files", "--", &path])
138	            .map(|listed| !listed.is_empty())
139	    }
140	
141	    /// Whether `path` (relative to this root) is on disk as `rev` recorded it, compared as Git compares: through its
142	    /// line-ending and attribute filters, so a checkout with CRLF endings matches the blob it was written from. Absent
143	    /// on both sides matches.
144	    pub fn path_matches_at(&self, rev: &str, path: &Path) -> Result<bool, VcsError> {
145	        Ok(self.blob_hash_at(rev, path)? == self.file_hash(path)?)
146	    }
147	
148	    /// The object id of `path` (relative to this root) in `rev`'s tree, or `None` when it is absent there.
149	    pub fn blob_hash_at(&self, rev: &str, path: &Path) -> Result<Option<String>, VcsError> {
150	        if !self.path_exists_at(rev, path)? {
151	            return Ok(None);
152	        }
153	        let spec = format!("{rev}:./{}", path.display());
154	        self.git_stdout(&["rev-parse", &spec]).map(Some)
155	    }
156	
157	    /// The object id Git would give the file at `path` (relative to this root) as it is on disk now, through its
158	    /// line-ending and attribute filters, or `None` when it is absent. Two ids are equal exactly when Git would
159	    /// store the same content.
160	    pub fn file_hash(&self, path: &Path) -> Result<Option<String>, VcsError> {
161	        let full = self.root().join(path);
162	        if !full.is_file() {
163	            return Ok(None);
164	        }
165	        let name = path.to_string_lossy();
166	        let file = full.to_string_lossy();
167	        self.git_stdout(&["hash-object", "--path", &name, &file]).map(Some)
168	    }
169	
170	    /// Checks the checkpoint at `name` out at `dir` (which must not exist) with `HEAD` on the commit the run started
171	    /// from, so history reads (commit inference) see the real commits and not the checkpoint's own. The files and the
172	    /// index stay as the checkpoint recorded them.
173	    pub fn add_checkpoint_worktree(&self, name: &str, dir: &Path, head: &str) -> Result<(), VcsError> {
174	        // The scratch checkout is internal: none of the user's hooks run in it, and a failed step takes its
175	        // registration with it.
176	        let dir_text = dir.to_string_lossy();
177	        let no_hooks = ["-c", "core.hooksPath=/dev/null"];
178	        let add: Vec<&str> = no_hooks
179	            .iter()
180	            .copied()
181	            .chain(["worktree", "add", "--detach", "--quiet", &dir_text, name])
182	            .collect();
183	        self.git_stdout(&add)?;
184	        let reset: Vec<&str> = no_hooks
185	            .iter()
186	            .copied()
187	            .chain(["reset", "--quiet", "--soft", head])
188	            .collect();
189	        let output = self.runner().run("git", &reset, dir)?;
190	        if !output.success() {
191	            self.remove_worktree(dir).ok();
192	            return Err(git_failed(&reset, dir, &output.stderr));
193	        }
194	        Ok(())
195	    }
196	
197	    /// This root's path inside the repository (empty at the top), so the same directory can be found in a worktree.
198	    pub fn root_prefix(&self) -> Result<std::path::PathBuf, VcsError> {
199	        self.git_stdout(&["rev-parse", "--show-prefix"])
200	            .map(std::path::PathBuf::from)
201	    }
202	
203	    /// The files under `dir` (relative to this root) in `rev`'s tree, relative to this root.
204	    pub fn files_at(&self, rev: &str, dir: &Path) -> Result<Vec<std::path::PathBuf>, VcsError> {
205	        let dir = dir.to_string_lossy();
206	        let listed = self.git_stdout(&["ls-tree", "-r", "-z", "--name-only", rev, "--", &dir])?;
207	        Ok(nul_separated(&listed).map(std::path::PathBuf::from).collect())
208	    }
209	
210	    /// Every file under this root with one of `names` as its file name, in `rev`'s tree or on disk (tracked or
211	    /// untracked, not ignored), relative to this root.
212	    pub fn files_named(
213	        &self,
214	        rev: &str,
215	        names: &[&str],
216	    ) -> Result<std::collections::BTreeSet<std::path::PathBuf>, VcsError> {
217	        let at_rev = self.git_stdout(&["ls-tree", "-r", "-z", "--name-only", rev, "--", "."])?;
218	        let on_disk = self.git_stdout(&[
219	            "ls-files",
220	            "-z",
221	            "--cached",
222	            "--others",
223	            "--exclude-standard",
224	            "--",
225	            ".",
226	        ])?;
227	        Ok(nul_separated(&at_rev)
228	            .chain(nul_separated(&on_disk))
229	            .map(std::path::PathBuf::from)
230	            .filter(|path| {
231	                path.file_name()
232	                    .and_then(|name| name.to_str())
233	                    .is_some_and(|name| names.contains(&name))
234	            })
235	            .collect())
236	    }
237	
238	    /// Removes a worktree [`Self::add_checkpoint_worktree`] added.
239	    pub fn remove_worktree(&self, dir: &Path) -> Result<(), VcsError> {
240	        let dir = dir.to_string_lossy();
241	        self.git_stdout(&["worktree", "remove", "--force", &dir]).map(drop)
242	    }
243	
244	    /// An unsigned commit of `tree` with fixed identity: it records state and is never pushed, so the user's signing
245	    /// key and identity play no part.
246	    fn internal_commit(&self, tree: &str, parents: &[&str], message: &str) -> Result<CommitSha, VcsError> {
247	        let mut args = vec![
248	            "-c",
249	            "user.name=Callisto",
250	            "-c",
251	            "user.email=callisto@localhost",
252	            "commit-tree",
253	            "--no-gpg-sign",
254	            tree,
255	        ];
256	        for parent in parents {
257	            args.extend(["-p", parent]);
258	        }
259	        args.extend(["-m", message]);
260	        let sha = self.git_stdout(&args)?;
261	        CommitSha::parse(&sha).map_err(|e| VcsError::InvalidCommitSha {
262	            context: "in `git commit-tree` output".to_string(),
263	            message: e.to_string(),
264	        })
265	    }
266	
267	    fn git_stdout(&self, args: &[&str]) -> Result<String, VcsError> {
268	        self.git_stdout_env(args, &[])
269	    }
270	
271	    fn git_stdout_env(&self, args: &[&str], env: &[(&str, &str)]) -> Result<String, VcsError> {
272	        let output = self.runner().run_with_env("git", args, self.root(), env)?;
273	        if !output.success() {
274	            return Err(git_failed(args, self.root(), &output.stderr));
275	        }
276	        Ok(output.stdout_line().to_string())
277	    }
278	}
279	
280	/// The entries of `-z` output: Git quotes no name there, so each is the path's own bytes.
281	fn nul_separated(listed: &str) -> impl Iterator<Item = &str> {
282	    listed.split('\0').filter(|entry| !entry.is_empty())
