        let git = GitAccess::new(temp.path(), &runner);

        let error = git
            .observe_git_commit_trust()
            .expect_err("untracked source must reject trust");

        assert!(matches!(error, VcsError::DirtyWorktree { path } if path == "release-input.txt"));
